insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 1, 'Revelação da palavra do SENHOR contra terra de Hadraque e de Damasco, seu repouso; porque os olhos da humanidade e de todas as tribos de Israel [estão voltados] ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 2, 'E também [contra] Hamate que faz fronteira com ela; Tiro e Sidom, ainda que seja muito sábia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 3, 'Tiro edificou para si fortalezas, e amontoou prata como pó da terra, e ouro como lama das ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 4, 'Eis que o Senhor a desapossará, e no mar ferirá sua fortaleza, e ela será consumida pelo fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 5, 'Asquelom verá, e temerá; Gaza também, e terá grande dor; assim como Ecrom, pois aquilo em que confiavam se envergonhará; o rei de Gaza perecerá, e Asquelom não será habitada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 6, 'E um povo misturado habitará em Asdode, e eu acabarei com a arrogância dos filisteus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 7, 'E tirarei seu sangue de sua boca, e suas abominações dentre seus dentes; porém os que restarem serão para nosso Deus, e serão como príncipes em Judá; e Ecrom será como o jebuseu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 8, 'E me acamparei ao redor de minha casa [contra] o exército [inimigo] ,para que não passe nem volte; para que o opressor não passe mais por eles; porque agora eu vi com meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 9, 'Alegra-te muito, ó filha de Sião; dá vozes de júbilo, ó filha de Jerusalém; eis que teu rei virá a ti, justo e salvador, humilde, e montado sobre um asno, sobre um jumentinho, filho de jumenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 10, 'E destruirei as carruagens de Efraim, e os cavalos de Jerusalém; os arcos de guerra também serão quebrados; e ele falará paz às nações; e seu domínio será de mar a mar, e desde o rio até os confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 11, 'Quanto a ti, pelo sangue de teu pacto, eu libertei teus prisioneiros da cova em que não havia água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 12, 'Voltai-vos à fortaleza, ó prisioneiros que tendes esperança; hoje também vos anuncio que vos recompensarei em dobro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 13, 'Pois encurvarei a Judá para mim como arco, porei a Efraim como flecha; e despertarei teus filhos, ó Sião, contra teus filhos, ó Grécia; e farei de ti, [Sião] , como espada de guerreiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 14, 'E o SENHOR será visto acima deles, e sua flecha sairá como relâmpago; o Senhor DEUS tocará trombeta, e irá como os turbilhões do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 15, 'O SENHOR dos exércitos os protegerá, e eles consumirão, e sujeitarão [com] pedras da funda; também beberão e farão gritarias como [bêbados de] vinho; e se encherão como a bacia de sacrifício, ou como os cantos do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 16, 'E o SENHOR, Deus deles, os salvará naquele dia como o rebanho de seu povo; porque serão como pedras de coroa, erguidas na terra dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 9, 17, 'Pois como será grande sua prosperidade, e tamanha sua beleza! O trigo fortalecerá os rapazes, e o suco de uva as virgens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 1, 'Pedi, vós, ao SENHOR chuva no tempo da chuva tardia; o SENHOR faz relâmpagos, e lhes dará chuva abundante, e erva no campo a cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 2, 'Pois os ídolos falam ilusão, e os adivinhos veem falsidade, e falado sonhos ilusórios; com ilusão consolam; por isso eles foram embora como ovelhas, humilhadas, porque não havia pastor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 3, 'Minha ira se acendeu contra os pastores, e castigarei os bodes; mas o SENHOR dos exércitos visitará seu rebanho, a casa de Judá, e fará com que sejam como seu cavalo de honra na batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 4, 'De ele [sairá] a pedra angular, a estaca, e o arco da guerra; dele juntamente sairá todo dominador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 5, 'E serão como guerreiros que pisam [o inimigo] na lama das ruas na batalha; e lutarão, porque o SENHOR estará com eles; e envergonharão aos que montam em cavalos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 6, 'E eu fortalecerei a casa de Judá, e salvarei a casa de José; e voltarei a estabelecê-los, porque me compadeci deles; e serão como se eu não tivesse os rejeitado, porque eu sou o SENHOR, Deus deles, que os ouvirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 7, 'E Efraim será como guerreiro, e seu coração se alegrará como de vinho; seus filhos verão, e ficarão contentes; seus corações se alegrarão no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 8, 'Eu assoviarei a eles, e os ajuntarei, porque eu os resgatarei; e serão muitos assim como eram muitos [no passado] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 9, 'E eu os semearei entre os povos, e se lembrarão de mim em lugares remotos; e viverão com seus filhos, e voltarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 10, 'Eu os trarei de volta da terra do Egito, e os recolherei da Assíria; e os trarei à terra de Gileade e do Líbano, mas não será [espaço] suficiente para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 11, 'Ele passará pela mar da aflição, ferirá as ondas do mar, e todas as profundezas do rio se secarão; e a arrogância dos assírios será derrubada, e o cetro do Egito será tomado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 10, 12, 'E eu os fortificarei no SENHOR, e andarão em seu nome, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 1, 'Abre tuas portas, ó Líbano, para que o fogo consuma teus cedros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 2, 'Lamenta, ó cipreste, porque o cedro caiu, porque os maiorais foram destruídos. Lamentai, ó carvalhos de Basã, porque o forte bosque foi derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 3, '[Ouve-se] voz de lamentação de pastores, porque sua glória foi destruída; [ouve-se] voz dos bramidos de leões jovens, porque a arrogância do Jordão foi destruída.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 4, 'Assim diz o SENHOR meu Deus: Apascenta as ovelhas da matança,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 5, 'Cujos compradores as matam, e ninguém os considera culpados; e os que as vendem dizem: Bendito seja o SENHOR, porque estou rico; nem seus pastores se compadecem delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 6, 'Certamente não mais pouparei os moradores da terra,diz o SENHOR; mas eis que eu entregarei os homens, cada um na mão de seu próximo, e em mão de seu rei; e despedaçarão esta terra, e eu não [os] livrarei de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 7, 'Então eu apascentei as ovelhas da matança, as pobres do rebanho. E tomei para mim duas varas; a uma chamei Agrado e à outra chamei União; e apascentei as ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 8, 'E acabei com três pastores em um mês, pois minha alma estava impaciente com eles, e também a almas deles me odiavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 9, 'E eu disse: Não vos apascentarei; a que morrer, morra; e a que se perder, se perca; e as que restarem, que uma devore a carne da outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 10, 'E peguei minha vara Agrado, e a quebrei, para desfazer meu pacto que tinha estabelecido com todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 11, 'Assim foi desfeito naquele dia, e assim as pobres do rebanho que me observavam reconheceram que isto era palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 12, 'Pois eu havia lhes dito: Se vos parece bem aos vossos olhos, dai-me meu salário; e se não, deixai-o. E pesaram meu salário: trinta [moedas] de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 13, 'O SENHOR, pois, me disse: Lança-as ao oleiro, este belo preço que me avaliaram.E tomei as trinta [moedas] de prata, e as lancei na casa do SENHOR ao oleiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 14, 'Então quebrei logo minha segunda vara União, rompendo a fraternidade entre Judá e Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 15, 'E o SENHOR me disse mais: Toma ainda para ti os instrumentos de um pastor insensato;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 16, 'Porque eis que eu levantarei um pastor na terra, que não cuidará das perdidas, não buscará a pequena, não tratará de curar a que estiver machucada, nem apascentará a sã; em vez disso, ele comerá a carne da que estiver gorda, e quebrará suas unhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 11, 17, 'Ai do pastor inútil, que desampara o rebanho! Espada [virá] contra seu braço, e contra seu olho direito; seu braço se secará por completo, e seu olho direito será obscurecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 1, 'Revelação da palavra do SENHOR sobre Israel: O SENHOR, que estende o céu, e funda a terra, e forma o espírito do ser humano em seu interior, diz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 2, 'Eis que eu farei de Jerusalém um copo de cambalear a todos os povos de ao redor; e também será sobre Judá, durante o cerco contra Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 3, 'E será naquele dia, que farei de Jerusalém uma pedra pesada a todos os povos; todos os que a carregarem serão seriamente feridos, ainda que todas as nações da terra se ajuntarão contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 4, 'Naquele dia,diz o SENHOR, ferirei com espanto a todo cavalo, e com loucura ao cavaleiro; mas sobre a casa de Judá abrirei meus olhos, e a todo cavalo dos povos ferirei com cegueira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 5, 'Então os líderes de Judá dirão em seu coração: Os moradores de Jerusalém serão minha força no SENHOR dos exércitos seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 6, 'Naquele dia farei dos líderes de Judá como um braseiro de fogo debaixo da lenha, e como tocha de fogo debaixo de gravetos; e consumirão todos os povos ao redor à direita e à esquerda; e Jerusalém continuará habitada em seu lugar, em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 7, 'E o SENHOR salvará primeiramente as tendas de Judá, para que a glória da casa de Davi e a glória dos moradores de Jerusalém não se exaltem sobre Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 8, 'Naquele dia o SENHOR defenderá os moradores de Jerusalém; e o que mais fraco dentre eles, naquele dia será como Davi; e a casa de Davi será como Deus, como o anjo do SENHOR diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 9, 'E será naquele dia que eu buscarei destruir todas as nações que vierem contra Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 10, 'Porém sobre a casa de Davi e sobre os moradores de Jerusalém derramarei o Espírito de graça e de orações; e olharão a mim, a quem traspassaram; e farão pranto sobre ele, como pranto [da morte] de filho único; e chorarão amargamente por causa dele, tal como se chora pelo primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 11, 'Naquele dia haverá grande pranto em Jerusalém, como o pranto de Hadade-Rimom no vale de Megido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 12, 'E a terra prateará, cada família por si só; a família da casa de Davi por si, e suas mulheres por si; a família da casa de Natã por si, e suas mulheres por si;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 13, 'A família da casa de Levi por si, e suas mulheres por si; a família de Simei por si, e suas mulheres por si;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 12, 14, 'Todos as demais famílias, cada família por si, e suas mulheres por si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 1, 'Naquele dia haverá uma fonte aberta para a casa de Davi e para os moradores de Jerusalém, contra o pecado e a impureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 2, 'E será naquele dia,diz o SENHOR dos exércitos, que eliminarei da terra os nomes dos ídolos, de modo nunca mais serão lembrados; e também eliminarei da terra os profetas e o espírito impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 3, 'E será que, quando alguém vier a profetizar, seu pai e sua mãe que o geraram lhe dirão: Não viverás, porque tens falado mentira no nome do SENHOR; e seu pai e sua mãe que o geraram o traspassarão quando profetizar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 4, 'E será naquele dia, que os profetas se envergonharão, cada um de sua visão, quando profetizarem; e nunca mais se vestirão de manto de pelos para mentir'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 5, 'Em vez disso, dirá: Não sou profeta; sou lavrador da terra, porque fui feito servo de um homem desde minha juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 6, 'E se lhe perguntarem: Que feridas são estas em tuas mãos? Ele responderá: Com elas fui ferido na casa de meus amigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 7, 'Desperta-te, ó espada, contra o pastor e contra o homem que é companheiro,diz o SENHOR dos exércitos. Fere ao pastor, e as ovelhas se dispersarão; e voltarei minha mão sobre os pequenos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 8, 'E será em toda a terra,diz o SENHOR, que as duas partes serão exterminadas nela, e perecerão; mas a terceira parte restará nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 13, 9, 'E porei esta terceira parte no fogo, e a refinarei como se refina a prata; e eu os provarei como se prova o ouro. Eles invocarão o meu nome, e eu lhes ouvirei; direi: São meu povo; e eles dirão: O SENHOR é meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 1, 'Eis que vem o dia do SENHOR, e teus despojos serão repartidos no meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 2, 'Porque eu ajuntarei todas as nações em batalha contra Jerusalém; e a cidade será tomada, as casas serão saqueadas, e as mulheres forçadas; e a metade da cidade irá em cativeiro, mas o restante do povo não será exterminado da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 3, 'Então o SENHOR virá, e lutará contra essas nações, como ele lutou no dia da batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 4, 'E naquele dia seus pés estarão sobre o monte das Oliveiras, que está em frente de Jerusalém ao oriente; e o monte das Oliveiras se fenderá por meio para oriente e para o ocidente, fazendo um vale muito grande; e metade do monte se moverá ao norte, e a [outra] metade ao sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 5, 'Então fugireis [pelo] vale dos montes (porque o vale dos montes chegará até Azal); e fugireis como fugistes por causa do terremoto nos dias de Uzias, rei de Judá; então o SENHOR meu Deus virá, e todos os santos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 6, 'E será naquele dias, que não haverá luz clara, nem espessa escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 7, 'E será um dia que, o SENHOR sabe como, não será dia nem noite; mas acontecerá no tempo do anoitecer haverá luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 8, 'Naquele dia também acontecerá, que de Jerusalém correrão águas vivas, a metade delas para o mar oriental, e a outra ao mar ocidental, tanto no verão como no inverno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 9, 'E o SENHOR será rei sobre toda a terra. Naquele dia o SENHOR será um, e seu nome um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 10, 'E toda esta terra se tornará como planície desde Geba até Rimom, ao sul de Jerusalém; porém esta será elevada, e habitada em seu lugar, desde a porta de Benjamim até o lugar da primeira porta, até a porta da esquina; e desde a torre de Hananel até as prensas de uvas do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 11, 'E habitarão nela, e nunca mais haverá maldição [sobre ela] ; porque Jerusalém habitará em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 12, 'E esta será a praga com que o SENHOR ferirá a todos os povos que guerrearam contra Jerusalém: a carne deles se apodrecerá estando eles sobre seus pés, seus olhos se apodrecerão em suas órbitas, e sua língua se lhes apodrecerá em sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 13, 'Naquele dia também acontecerá que haverá grande tumulto do SENHOR entre eles; por isso cada um pegará na mão de seu próximo, e sua mão se levantará contra a mão de seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 14, 'E Judá também lutará em Jerusalém. E a riqueza de todas as nações de ao redor será ajuntada: ouro, prata, e roupas, em grande abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 15, 'Assim também como esta praga, será a praga para os cavalos, os jumentos, os camelos, os asnos, e todos os animais que estiverem naqueles acampamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 16, 'E será que, todos os que restarem de todas as nações que vieram contra Jerusalém subirão de ano em ano para adorarem ao rei, o SENHOR dos exércitos, e a celebrarem a festa dos tabernáculos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 17, 'E acontecerá que, se alguma das famílias da terra não subir a Jerusalém para adorar ao rei, o SENHOR dos exércitos, não virá chuva sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 18, 'E se a família do Egito não subir, e não vier, não virá [chuva] sobre eles; virá a praga com que o SENHOR ferirá as nações que não subirem para celebrar a festa dos tabernáculos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 19, 'Esta será a [punição pelo] pecado do Egito, e [pelo] pecado de todas as nações que não subirem para celebrar a festa dos tabernáculos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 20, 'Naquele tempo sobre as sinos dos cavalos estará: CONSAGRADO AO SENHOR; e as panelas na casa do SENHOR serão como as bacias diante do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 14, 21, 'E todas as panelas em Jerusalém e em Judá serão consagradas ao SENHOR dos exércitos, de modo que todos os que sacrificarem, virão e delas tomarão, e nelas cozerão; e naquele dia não haverá mais cananeu algum na casa do SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 1, 'Revelação da palavra do SENHOR a Israel, por meio de Malaquias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 2, 'Eu vos tenho amado,diz o SENHOR; mas vos dizeis: Em que nos amaste? Não era Esaú irmão de Jacó?, diz o SENHOR, todavia amei a Jacó,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 3, 'E odiei a Esaú; e tornei seus montes em desolação, e sua herança para os chacais do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 4, 'Ainda que Edom diga: Fomos devastados, mas voltaremos a edificar as ruínas; assim diz o SENHOR dos exércitos: Eles edificarão, e eu destruirei; e serão chamados de “território da perversidade” e “povo contra quem o SENHOR está irado para sempre”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 5, 'E vossos olhos verão, e direis: Seja o SENHOR engrandecido até além do território de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 6, 'O filho honra ao pai, e o servo a seu senhor; se pois sou eu pai, onde está minha honra? E se sou senhor, onde está o temor a mim?,diz o SENHOR dos exércitos a vós, sacerdotes, que desprezais o meu nome. Mas vós dizeis: Em que temos desprezado o teu nome?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 7, 'Quando trazeis sobre meu altar pão contaminado. E dizeis: Em que te contaminamos? Quando dizeis: A mesa do SENHOR é desprezível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 8, 'E quando trazeis [animal] cego para o sacrifício, isso não é mal? E quando trazeis o aleijado ou o enfermo, isso não é mal? Apresenta isso a teu governador; por acaso ele se agradará de ti, ou ele te aceitará? diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 9, 'Agora pois, suplicai o favor de Deus que ele tenha compaixão de nós; será, por acaso, que com isto que tendes feito por vossas mãos, ele vos aceitará?,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 10, 'Quem, pois, há de vós que feche as portas? Pelo menos assim vós não acenderíeis o fogo de meu altar em vão! Eu não tenho prazer em vós,diz o SENHOR dos exércitos, e não me agrado da oferta de vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 11, 'Pois desde o oriente até o ocidente o meu nome será grande entre as nações; e em todo lugar se oferecerá a meu nome incenso e oferta pura; porque meu nome será grande entre as nações,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 12, 'Mas vós o profanais quando dizeis: A mesa do SENHOR está contaminada; e seu produto, o alimento, é desprezível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 13, 'Além disso, dizeis: É cansativo demais! E o desprezais, diz o SENHOR dos exércitos; vós trazeis o roubado, o aleijado, e o enfermo, e trazeis a oferta. Por acaso aceitaria isso de vossas mãos?, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 1, 14, 'Maldito seja o mentiroso, que tem macho em seu rebanho, e promete, mas sacrifica o defeituoso ao SENHOR; pois eu sou o Grande Rei,diz o SENHOR dos exércitos, e meu nome é temível entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 1, 'Agora pois, ó sacerdotes, este mandamento é para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 2, 'Se não [o] ouvirdes, e se não guardardes no coração de dar glória a meu nome,diz o SENHOR dos exércitos, enviarei maldição sobre vós, e amaldiçoarei vossas bênçãos. Aliás, eu já as tenho amaldiçoado, porque não tendes guardado [isso] no vosso coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 3, 'Eis que eu repreenderei a vossa descendência, e espalharei lixo sobre os vossos rostos, o lixo de vossas festas, e com ele sereis removidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 4, 'Então sabereis que eu vos enviei este mandamento, para que meu pacto seja com Levi,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 5, 'Meu pacto foi com ele de vida e de paz, as quais eu lhe dei para haver temor; e ele me temeu, e teve medo diante de meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 6, 'A lei de verdade estava em sua boca, e não se achou injustiça em seus lábios; ele andava comigo em paz e em justiça, e converteu a muitos da maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 7, 'Porque os lábios do sacerdote devem guardar o conhecimento, e de sua boca devem buscar a lei; porque ele é mensageiro do SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 8, 'Mas vós vos desviastes do caminho; fizestes tropeçar a muitos na lei; corrompestes o pacto de Levi,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 9, 'Por isso eu também vos tornei desprezíveis e indignos diante de todo o povo, visto que não guardais meus caminhos, e na lei fazeis acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 10, 'Não temos todos um [mesmo] Pai? Não foi um [mesmo] Deus que nos criou? Por que, [então] , traímos cada um a seu irmão, profanando o pacto de nossos pais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 11, 'Judá tem agido com traição, e abominação se comete em Israel e em Jerusalém; porque Judá profana o santuário do SENHOR, o qual ele ama, e se casou com filha de deus estranho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 12, 'O SENHOR removerá das tendas de Jacó ao homem que fizer isto, ao que vela, e ao que responde, e ao que traz oferta ao SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 13, 'Também fazeis esta segunda coisa: cobris o altar do SENHOR de lágrimas, de pranto, e de gemidos; por isso ele não dará mais atenção à oferta, nem a aceitará com prazer de vossa mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 14, 'Vós dizeis: Por que razão? Porque o SENHOR foi testemunha entre ti e a mulher de tua juventude, contra a qual tu tens traído, sendo ela a tua companheira, e a mulher de teu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 15, 'E não fez ele somente um ainda que lhe sobre o espírito? E por que um? Para buscar uma descendência de Deus. Guardai-vos pois em vosso espírito, e ninguém de vós seja infiel à mulher de vossa juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 16, 'Porque o SENHOR Deus de Israel diz que ele odeia o divórcio, e [quem] cobre a sua roupa de violência, diz o SENHOR dos exércitos. Guardai-vos pois em vosso espírito, e não sejais infiéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 2, 17, 'Cansais ao SENHOR com vossas palavras. E ainda dizeis: Em que nós [o] cansamos? Quando dizeis: Qualquer um que faz o mal é bom aos olhos ao SENHOR, que se agrada deles; ou: Onde está o Deus do juízo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 1, 'Eis que eu enviarei o meu mensageiro, que preparará o caminho adiante de mim; e de repente virá a seu templo o Senhor a quem vós buscais, o mensageiro do pacto a quem vós desejais. Eis que ele vem,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 2, 'Mas quem poderá suportar o dia de sua vinda? Quem conseguirá ficar de pé quando ele aparecer? Porque ele será como fogo do ourives, e como o sabão de lavandeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 3, 'E ele se sentará como refinador e purificador da prata; pois ele limpará os filhos de Levi, e os refinará como o ouro e como a prata; então trarão ao SENHOR oferta com justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 4, 'E a oferta de Judá e de Jerusalém será suave ao SENHOR, como nos dias antigos, e como nos anos passados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 5, 'E eu me achegarei a vós para o julgamento; e prontamente serei testemunha contra os feiticeiros e adúlteros, e contra os que juram falsamente, e os que oprimem o empregado em seu salário, a viúva, e o órfão, e pervertem [o direito] do estrangeiro, e não me temem,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 6, 'Porque eu o SENHOR, não me mudo; por isso que vós, filhos de Jacó, não sois consumidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 7, 'Desde os dias de vossos pais vos desviastes de minhas leis, e não as guardastes. Voltai-vos a mim, e eu me voltarei a vós,diz o SENHOR dos exércitos. Mas vós dizeis: Em que temos de voltar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 8, 'Pode o ser humano roubar a Deus? Vós, pois, me roubais. Mas vós dizeis: Em que te roubamos? Nos dízimos e nas ofertas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 9, 'Com maldição sois amaldiçoados porque vós me roubais, toda a nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 10, 'Trazei todos os dízimos à casa do tesouro, para que haja alimento em minha casa; e provai-me nisto, diz o SENHOR dos exércitos, se não vos abrir as janelas dos céu, e derramar sobre vós bênção transbordante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 11, 'E por causa de vós repreenderei ao devorador, para não corrompa vosso fruto da terra; e vossa vide no campo não será estéril,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 12, 'E todas as nações vos chamarão bem-aventurados; porque vós sereis terra agradável,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 13, 'Vossas palavras têm sido duras contra mim,diz o SENHOR. Mas vós dizeis: O que temos falado contra ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 14, 'Vós dizeis: É inútil servir a Deus; pois que proveito [temos tido] em guardarmos seus mandamentos e andarmos lamentando diante do SENHOR dos exércitos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 15, 'Chamemos de sortudos os soberbos, pois os que praticam perversidade prosperam; mesmo tentando a Deus, eles escapam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 16, 'Então aqueles que temeram ao SENHOR falaram cada um a seu próximo, e o SENHOR prestou atenção e ouviu; e foi escrito um livro de memória diante dele para os que temem ao SENHOR, e para os que se honraram o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 17, 'E eles serão minha propriedade especial no dia que eu preparo,diz o SENHOR dos exércitos; e os pouparei como o homem que poupa a seu filho que lhe serve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 3, 18, 'Então voltareis a ver a diferença entre o justo e o perverso, entre o que serve a Deus e o que não lhe serve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 4, 1, 'Porque eis que aquele dia vem ardendo como forno; todos os soberbos e todos os que praticam perversidade serão [como a] palha; e o dia que está por vir os queimará, diz o SENHOR dos exércitos, de maneira que não lhes deixará nem raiz nem ramo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 4, 2, 'Mas para vós, que temeis o meu nome, o Sol da justiça nascerá, trazendo cura em suas asas; e saireis, e saltareis de alegria como bezerros do curral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 4, 3, 'E pisareis os perversos, porque serão cinza debaixo das plantas dos vossos pés, no dia que eu preparo, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 4, 4, 'Lembrai-vos da lei de meu servo Moisés, que lhe mandei em Horebe estatutos e regras para todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 4, 5, 'Eis que eu vos envio o profeta Elias, antes que venha o grande e temível dia do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 39, 'Malaquias', 'Ml', 4, 6, 'Ele converterá o coração dos pais aos filhos, e o coração dos filhos aos pais; para que eu não venha e fira a terra com maldição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 1, 'Livro da geração de Jesus Cristo, filho de Davi, filho de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 2, 'Abraão gerou a Isaque; e Isaque gerou a Jacó; e Jacó gerou a Judá e a seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 3, 'E Judá gerou de Tamar a Perez e a Zerá; e Perez gerou a Esrom, e Esrom gerou a Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 4, 'E Arão gerou a Aminadabe; e Aminadabe gerou a Naassom; e Naassom gerou a Salmom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 5, 'E Salmom gerou de Raabe a Boaz; e Boaz gerou de Rute a Obede; e Obede gerou a Jessé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 6, 'E Jessé gerou ao rei Davi; e o rei Davi gerou Salomão da que [fora mulher] de Urias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 7, 'E Salomão gerou a Roboão; e Roboão gerou a Abias; e Abias gerou a Asa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 8, 'E Asa gerou a Josafá; e Josafá gerou a Jorão; e Jorão gerou a Uzias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 9, 'E Uzias gerou a Jotão; e Jotão gerou a Acaz; e Acaz gerou a Ezequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 10, 'E Ezequias gerou a Manassés; e Manassés gerou a Amom; e Amom gerou a Josias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 11, 'E Josias gerou a Jeconias, e a seus irmãos no [tempo do] exílio babilônico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 12, 'E depois do exílio babilônico Jeconias gerou a Salatiel; e Salatiel gerou a Zorobabel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 13, 'E Zorobabel gerou a Abiúde; e Abiúde gerou a Eliaquim; e Eliaquim gerou a Azor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 14, 'E Azor gerou a Sadoque; e Sadoque gerou a Aquim; e Aquim gerou a Eliúde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 15, 'E Eliúde gerou a Eleazar; e Eleazar gerou a Matã; e Matã gerou a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 16, 'E Jacó gerou a José, o marido de Maria, da qual nasceu Jesus, chamado o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 17, 'De maneira que todas as gerações desde Abraão até Davi são catorze gerações; e desde Davi até o exílio babilônico catorze gerações; e desde o exílio babilônico até Cristo catorze gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 18, 'E o nascimento de Jesus Cristo foi assim: estando sua mãe Maria desposada com José, antes que se ajuntassem, ela foi achada grávida do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 19, 'Então José, seu marido, sendo justo, e não querendo a expor à infâmia, pensou em deixá-la secretamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 20, 'E ele, pretendendo isto, eis que um anjo do Senhor lhe apareceu em sonho, dizendo: José, filho de Davi, não temas receber Maria, tua mulher, porque o que nela está concebido é do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 21, 'E ela dará à luz um filho, e tu chamarás seu nome Jesus; porque ele salvará seu povo de seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 22, 'E tudo isto aconteceu para que se cumprisse o que foi dito pelo Senhor por meio do profeta, que disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 23, 'Eis que a virgem conceberá, e dará à luz um filho, e chamarão seu nome Emanuel, que traduzido é: Deus conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 24, 'E despertando José do sonho, fez como o anjo do Senhor tinha lhe mandado, e recebeu sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 1, 25, 'E ele não a conheceu [intimamente] ,até que ela deu à luz o filho dela, o primogênito, e lhe pôs por nome JESUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 1, 'E sendo Jesus já nascido em Belém da Judeia, nos dias do rei Herodes, eis que vieram uns magos do oriente a Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 2, 'Dizendo: Onde está o Rei nascido dos Judeus? Porque vimos sua estrela no oriente, e viemos adorá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 3, 'E o rei Herodes, ao ouvir [isto] , ficou perturbado, e com ele toda Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 4, 'E tendo reunido todos os chefes dos sacerdotes e escribas do povo, perguntou-lhes onde o Cristo havia de nascer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 5, 'E eles lhe disseram: Em Belém da Judeia, porque assim está escrito pelo profeta:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 6, 'E tu Belém, terra de Judá, de maneira nenhuma és a menor entre as lideranças de Judá, porque de ti sairá o Guia que apascentará meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 7, 'Então Herodes, chamando secretamente os magos, perguntou-lhes com precisão sobre o tempo em que a estrela havia aparecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 8, 'E enviando-os a Belém, disse: Ide, e investigai cuidadosamente pelo menino; e quando o achardes, avisai-me, para que também eu venha e o adore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 9, 'Depois de ouvirem o rei, eles foram embora. E eis que a estrela que tinham visto no oriente ia adiante deles, até que ela chegou, e ficou parada sobre onde o menino estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 10, 'E eles, vendo a estrela, jubilaram muito com grande alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 11, 'E entrando na casa, acharam o menino com sua mãe Maria, e prostrando-se o adoraram. E abrindo seus tesouros, ofereceram-lhe presentes: ouro, incenso, e mirra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 12, 'E sendo por divina revelação avisados em sonho que não voltassem a Herodes, partiram para sua terra por outro caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 13, 'E tendo eles partido, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, e foge para o Egito; e fica lá até que eu te diga, porque Herodes buscará o menino para o matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 14, 'Então ele se despertou, tomou o menino e sua mãe de noite, e foi para o Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 15, 'E esteve lá até a morte de Herodes, para que se cumprisse o que foi dito pelo Senhor por meio do profeta, que disse: Do Egito chamei o meu Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 16, 'Então Herodes, ao ver que tinha sido enganado pelos magos, irou-se muito, e mandou matar todos os meninos em Belém e em todos os limites de sua região, [da idade] de dois anos e abaixo, conforme o tempo que tinha perguntado com precisão dos magos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 17, 'Então se cumpriu o que foi dito pelo profeta Jeremias, que disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 18, 'Uma voz se ouviu em Ramá, lamentação, choro, e grande pranto; Raquel chorava por seus filhos, e não quis ser consolada, pois já não existem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 19, 'Mas depois de Herodes ter morrido, eis que um anjo do Senhor apareceu no Egito a José em sonho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 20, 'Dizendo: Levanta-te, toma o menino e sua mãe, e vai para a terra de Israel, porque já morreram os que procuravam a morte do menino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 21, 'Então ele se levantou, tomou o menino e sua mãe, e veio para a terra de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 22, 'Porém ao ouvir que Arquelau reinava na Judeia em lugar de seu pai Herodes, ele teve medo de ir para lá; mas avisado por divina revelação em sonho, foi para a região da Galileia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 2, 23, 'E veio a habitar na cidade chamada Nazaré, para que se cumprisse o que foi dito pelos profetas, que: Ele será chamado de Nazareno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 1, 'E naqueles dias veio João Batista, pregando no deserto da Judeia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 2, 'E dizendo: Arrependei-vos, porque perto está o Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 3, 'Porque este é aquele que foi declarado pelo profeta Isaías, que disse: Voz do que clama no deserto: “Preparai o caminho do Senhor; endireitai suas veredas”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 4, 'Este João tinha sua roupa de pelos de camelo e um cinto de couro ao redor de sua cintura, e seu alimento era gafanhotos e mel silvestre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 5, 'Então vinham até ele [moradores] de Jerusalém, de toda a Judeia, e de toda a região próxima do Jordão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 6, 'E eram por ele batizados no Jordão, confessando os seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 7, 'Mas quando ele viu muitos dos fariseus e dos saduceus que vinham ao seu batismo, disse-lhes: Ninhada de víboras! Quem vos ensinou a fugir da ira futura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 8, 'Dai, pois, frutos condizentes com o arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 9, 'E não imagineis, dizendo em vós mesmos: “Temos por pai a Abraão”, porque eu vos digo que até destas pedras Deus pode fazer surgir filhos a Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 10, 'E agora mesmoo machado está posto à raiz das árvores; portanto toda árvore que não dá bom fruto é cortada e lançada ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 11, 'Realmente eu vos batizo com água para arrependimento, mas aquele que vem após mim é mais poderoso do que eu; suas sandálias não sou digno de levar. Ele vos batizará com o Espírito Santo e com fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 12, 'Ele tem sua pá na mão; limpará sua eira, e recolherá seu trigo no celeiro; mas queimará a palha com fogo que nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 13, 'Então Jesus veio da Galileia ao Jordão até João para ser por ele batizado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 14, 'Mas João lhe impedia, dizendo: Eu preciso ser batizado por ti, e tu vens a mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 15, 'Porém Jesus lhe respondeu: Permite por agora, porque assim nos convém cumprir toda a justiça. Então ele o permitiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 16, 'E tendo Jesus sido batizado, subiu logo da água. E eis que os céus se lhe abriram, e ele viu o Espírito de Deus descendo como uma pomba, vindo sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 3, 17, 'E eis uma voz dos céus, dizendo: Este é o meu Filho amado, em quem me agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 1, 'Então Jesus foi levado pelo Espírito ao deserto para ser tentado pelo diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 2, 'E depois de jejuar quarenta dias e quarenta noites, teve fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 3, 'E o tentador se aproximou dele, e disse: Se tu és o Filho de Deus, dize que estas pedras se tornem pães.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 4, 'Mas [Jesus] respondeu: Está escrito: Não só de pão viverá o ser humano, mas de toda palavra que sai da boca de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 5, 'Então o diabo o levou consigo à santa cidade, e o pôs sobre o ponto mais alto do Templo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 6, 'E disse-lhe: Se tu és o Filho de Deus, lança-te abaixo, porque está escrito que: Mandará a seus anjos acerca de ti, e te tomarão pelas mãos, para que nunca com teu pé tropeces em pedra alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 7, 'Jesus lhe disse: Também está escrito: Não tentarás o Senhor teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 8, 'Outra vez o diabo o levou consigo a um monte muito alto, e lhe mostrou todos os reinos do mundo, e a glória deles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 9, 'E disse-lhe: Tudo isto te darei se, prostrado, me adorares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 10, 'Então Jesus disse: Vai embora, Satanás! Porque está escrito: Ao Senhor teu Deus adorarás, e só a ele cultuarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 11, 'Então o diabo o deixou; e eis que chegaram anjos, e o serviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 12, 'Mas quando Jesus ouviu que João estava preso, voltou para a Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 13, 'E deixando Nazaré, veio a morar em Cafarnaum, [cidade] marítima, nos limites de Zebulom e Naftali,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 14, 'para que se cumprisse o que foi anunciado pelo profeta Isaías, que disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 15, 'A terra de Zebulom e a terra de Naftali, caminho do mar, além do Jordão, a Galileia dos gentios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 16, 'O povo sentado em trevas viu uma grande luz; aos sentados em região e sombra da morte, a luz lhes apareceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 17, 'Desde então Jesus começou a pregar e a dizer: Arrependei-vos, porque perto está o Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 18, 'Enquanto Jesus andava junto ao mar da Galileia, viu dois irmãos: Simão, chamado Pedro, e seu irmão André, lançarem a rede ao mar, porque eram pescadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 19, 'E disse-lhes: Vinde após mim, e eu vos farei pescadores de gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 20, 'Então eles logo deixaram as redes e o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 21, 'E passando dali, viu outros dois irmãos: Tiago, [filho] de Zebedeu, e seu irmão João, em um barco, com seu pai Zebedeu, que estavam consertando suas redes; e ele os chamou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 22, 'E eles logo deixaram o barco e seu pai, e o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 23, 'E Jesus rodeava toda a Galileia, ensinando em suas sinagogas, pregando o Evangelho do Reino, e curando toda enfermidade e toda doença no povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 24, 'Sua fama corria por toda a Síria, e traziam-lhe todos que sofriam de algum mal, tendo diversas enfermidades e tormentos, e os endemoninhados, epiléticos, e paralíticos; e ele os curava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 4, 25, 'E muitas multidões da Galileia, de Decápolis, de Jerusalém, da Judeia, e dalém do Jordão o seguiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 1, 'E quando [Jesus] viu as multidões, subiu a um monte; e sentando-se, achegaram-se a ele os seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 2, 'Então ele abriu sua boca e lhes ensinou, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 3, 'Benditos são os humildes de espírito, porque deles é o Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 4, 'Benditos são os que choram, porque eles serão consolados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 5, 'Benditos são os mansos, porque eles herdarão a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 6, 'Benditos são os que têm fome e sede de justiça, porque eles serão saciados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 7, 'Benditos são os misericordiosos, porque eles alcançarão misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 8, 'Benditos são os limpos de coração, porque eles verão a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 9, 'Benditos são os pacíficos, porque eles serão chamados filhos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 10, 'Benditos são os que sofrem perseguição por causa da justiça, porque deles é o Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 11, 'Benditos sois vós, quando vos insultarem, perseguirem, e mentirem, falando contra vós todo mal por minha causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 12, 'Jubilai e alegrai-vos, porque grande é vossa recompensa nos céus; pois assim perseguiram aos profetas que foram antes de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 13, 'Vós sois o sal da terra; mas se o sal perder seu sabor, com que se salgará? Para nada mais presta, a não ser para se lançar fora, e ser pisado pelas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 14, 'Vós sois a luz do mundo; não se pode esconder uma cidade fundada sobre o monte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 15, 'Nem se acende a lâmpada para se pôr debaixo de um cesto, mas sim na luminária, e ilumina a todos quantos estão na casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 16, 'Assim brilhe vossa luz diante das pessoas, para que vejam vossas boas obras, e glorifiquem ao vosso Pai, que está nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 17, 'Não penseis que vim para revogar a Lei ou os Profetas; não vim para revogar, mas sim para cumprir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 18, 'Porque em verdade vos digo que, até que o céu e a terra passem, nem um jota nem um til passará da Lei até que tudo se cumpra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 19, 'Portanto qualquer um que desobedecer a um destes menores mandamentos, e assim ensinar às pessoas, será chamado o menor no Reino dos céus; porém qualquer que [os] cumprir e ensinar, esse será chamado grande no Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 20, 'Porque eu vos digo que se a vossa justiça não for maior que a dos escribas e dos fariseus, de maneira nenhuma entrareis no Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 21, 'Ouvistes o que foi dito aos antigos: “Não cometerás homicídio”; “mas qualquer um que cometer homicídio será réu do julgamento”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 22, 'Porém eu vos digo que qualquer um que se irar contra seu irmão sem razão será réu do julgamento. E qualquer um que disser a seu irmão: “Idiota!” será réu do tribunal. E qualquer que [lhe] disser: “Louco!” será réu do fogo do inferno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 23, 'Portanto, se trouxeres tua oferta ao altar, e ali te lembrares que teu irmão tem algo contra ti,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 24, 'Deixa ali tua oferta diante do altar e vai primeiro reconciliar-te com teu irmão, e então vem oferecer a tua oferta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 25, 'Faze acordo depressa com teu adversário, enquanto estás com ele no caminho, para não acontecer que o adversário te entregue ao juiz, e o juiz te entregue ao oficial, e te lancem na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 26, 'Em verdade te digo que não sairás dali enquanto não pagares a última moeda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 27, 'Ouvistes o que foi dito aos antigos: “Não adulterarás”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 28, 'Porém eu vos digo que qualquer um que olhar para uma mulher para a cobiçar, em seu coração já adulterou com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 29, 'Se o teu olho direito te faz pecar, arranca-o e lança-o de ti; porque é melhor para ti que um dos teus membros se perca do que o teu corpo todo seja lançado no inferno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 30, 'E se a tua mão direita te faz pecar, corta-a e lança-a de ti; porque é melhor para ti que um dos teus membros se perca do que o teu corpo todo seja lançado no inferno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 31, 'Também foi dito: “Qualquer um que se divorciar de sua mulher, dê a ela carta de divórcio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 32, 'Porém eu vos digo que qualquer um que se divorciar de sua mulher, a menos que seja por causa de pecado sexual, faz com que ela adultere; e qualquer um que se casar com a divorciada comete adultério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 33, 'Também ouvistes que foi dito aos antigos: “Não jurarás falsamente”, “mas cumprirás ao Senhor os teus juramentos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 34, 'Porém eu vos digo que de maneira nenhuma jureis; nem pelo céu, porque é o trono de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 35, 'Nem pela terra, porque é o suporte de seus pés; nem por Jerusalém, porque é a cidade do grande Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 36, 'Nem por tua cabeça jurarás, pois nem sequer um cabelo podes tornar branco ou preto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 37, 'Mas seja vosso falar: “sim”, “sim”, “não”, “não”; porque o que disso passa procede do maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 38, 'Ouvistes o que foi dito: “Olho por olho, e dente por dente”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 39, 'Mas eu vos digo que não resistais a quem for mau; em vez disso, a qualquer um que te bater à tua face direita, apresenta-lhe também a outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 40, 'E ao que quiser disputar contigo, e te tomar tua túnica, deixa-lhe também a capa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 41, 'E se qualquer um te obrigar a caminhar uma milha, vai com ele duas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 42, 'Dá a quem te pedir; e não te desvies de quem quiser de ti tomar emprestado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 43, 'Ouvistes o que foi dito: “Amarás teu próximo”, e “odiarás teu inimigo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 44, 'Porém eu vos digo: amai vossos inimigos, bendizei os que vos maldizem, fazei bem aos que vos odeiam, e orai pelos que vos maltratam e vos perseguem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 45, 'Para que sejais filhos de vosso Pai que está nos céus; porque ele faz seu sol sair sobre maus e bons, e chover sobre justos e injustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 46, 'Pois se amardes os que vos amam, que recompensa tereis? Não fazem os publicanos também o mesmo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 47, 'E se saudardes somente os vossos irmãos, o que fazeis de mais? Não fazem os publicanos também assim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 5, 48, 'Portanto, sede vós perfeitos, assim como vosso Pai que está nos céus é perfeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 1, 'Ficai atentos para que não façais vossa esmola diante das pessoas a fim de que sejais vistos por elas; de outra maneira não tereis recompensa de vosso Pai que está nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 2, 'Portanto, quando fizeres esmola, não faças tocar trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem honrados pelas pessoas; em verdade vos digo que já receberam sua recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 3, 'Mas quando tu fizeres esmola, não saiba tua mão esquerda o que faz a tua direita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 4, 'Para que a tua esmola seja em segredo, e teu Pai, que vê em segredo, ele te recompensará em público.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 5, 'E quando orares, não sejas como os hipócritas; porque eles amam orar em pé nas sinagogas e nas esquinas das ruas para serem vistos pelas pessoas. Em verdade vos digo que já receberam sua recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 6, 'Porém tu, quando orares, entra em teu quarto, fecha tua porta, e ora a teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 7, 'E quando orardes, não façais repetições inúteis como os gentios, que pensam que por muito falarem serão ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 8, 'Não sejais, pois, semelhantes a eles; porque vosso Pai sabe o que necessitais, antes que vós peçais a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 9, 'Vós, portanto, orareis assim: Pai nosso, que estás nos céus, santificado seja o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 10, 'Venha o teu Reino. Seja feita a tua vontade, tanto na terra, assim como no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 11, 'O pão nosso de cada dia nos dá hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 12, 'E perdoa-nos nossas dívidas, assim como nós também perdoamos aos nossos devedores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 13, 'E não nos conduzas à tentação, mas livra-nos do mal; porque teu é o Reino, o poder, e a glória, para sempre, Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 14, 'Porque se perdoardes às pessoas suas ofensas, vosso Pai celestial também vos perdoará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 15, 'Mas se não perdoardes às pessoas suas ofensas, também vosso Pai não vos perdoará vossas ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 16, 'E quando jejuardes, não vos mostreis tristonhos, como os hipócritas; porque eles desfiguram seus rostos, para parecerem aos outros que jejuam. Em verdade vos digo que eles já receberam sua recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 17, 'Porém tu, quando jejuares, unge a tua cabeça e lava o teu rosto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 18, 'Para não pareceres às pessoas que jejuas, mas sim ao teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 19, 'Não ajunteis para vós tesouros na terra, onde e a traça e a ferrugem gastam, e onde os ladrões invadem e roubam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 20, 'Mas ajuntai para vós tesouros no céu, onde nem a traça nem a ferrugem gastam, e onde os ladrões não invadem nem roubam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 21, 'Porque onde estiver o vosso tesouro, ali estará também o vosso coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 22, 'A lâmpada do corpo é o olho; portanto, se o teu olho for puro, todo o teu corpo será cheio de luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 23, 'Porém se o teu olho for maligno, todo o teu corpo será cheio de trevas. Assim, se a luz que há em ti são trevas, como são grandes [essas] trevas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 24, 'Ninguém pode servir a dois senhores; pois ou odiará um e amará outro; ou se apegará a um, e desprezará o outro. Não podeis servir a Deus e às riquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 25, 'Por isso vos digo: não andeis ansiosos por vossa vida, sobre o que haveis de comer, ou que haveis de beber; nem por vosso corpo, sobre com que vos haveis de vestir. Não é a vida mais que o alimento, e o corpo [mais] que a roupa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 26, 'Olhai para as aves do céu, que não semeiam, nem ceifam, nem ajuntam em celeiros; e contudo vosso Pai celestial as alimenta. Não sois vós muito mais importantes que elas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 27, 'E qual de vós poderá, por sua ansiedade, acrescentar um côvado à sua estatura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 28, 'E por que andais ansiosos pela roupa? Prestai atenção aos lírios do campo, como crescem; eles nem trabalham nem fiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 29, 'Mas eu vos digo que nem mesmo Salomão, em toda a sua glória, se vestiu como um deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 30, 'Se Deus veste desta maneira a erva do campo, que hoje existe, e amanhã é lançada no forno, não [vestirá] ele muito mais a vós, que tendes pouca fé?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 31, 'Não andeis, pois, ansiosos, dizendo: “Que comeremos?” Ou “Que beberemos?” Ou “Com que nos vestiremos?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 32, 'Porque os gentios buscam todas estas coisas, e vosso Pai celestial sabe que necessitais destas coisas, todas elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 33, 'Mas buscai primeiramente o Reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 6, 34, 'Não andeis, pois, ansiosos pelo dia de amanhã, porque o amanhã cuidará de si mesmo. Basta a cada dia o seu mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 1, 'Não julgueis, para que não sejais julgados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 2, 'Porque com o juízo que julgardes sereis julgados; e com a medida que medirdes vos medirão de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 3, 'Ora, por que vês o cisco que está no olho de teu irmão e não enxergas a trave que está em teu próprio olho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 4, 'Ou como dirás a teu irmão: “Deixa-me tirar o cisco do teu olho”, se eis que há uma trave em teu próprio olho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 5, 'Hipócrita! Tira primeiro a trave do teu olho, e então verás claramente para tirar o cisco do olho de teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 6, 'Não deis o que é santo aos cães, nem lanceis vossas pérolas diante dos porcos, para não acontecer de as pisarem com os pés e, virando-se, vos despedacem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 7, 'Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 8, 'Pois qualquer um que pede recebe; e quem busca acha; e ao que bate lhe é aberto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 9, 'E quem há dentre vós que, se seu filho pedir pão, lhe dará uma pedra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 10, 'E se pedir peixe, lhe dará uma serpente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 11, 'Ora, se vós, sendo maus, sabeis dar bons presentes a vossos filhos, quanto mais o vosso Pai, que está nos céus, dará coisas boas aos que lhe pedirem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 12, 'Portanto tudo o que quiserdes que os outros vos façam, fazei-lhes vós também assim; porque esta é a Lei e os Profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 13, 'Entrai pela porta estreita; porque larga é a porta, e espaçoso o caminho que leva à perdição; e muitos são os que por ela entram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 14, 'Porque estreita é a porta, e apertado o caminho que leva à vida; e são poucos os que a acham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 15, 'Tende cuidado, porém, com os falsos profetas, que vêm a vós com roupa de ovelhas, mas por dentro são lobos vorazes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 16, 'Vós os conhecereis pelos seus frutos. Por acaso se colhem uvas dos espinheiros, ou figos dos cardos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 17, 'Assim toda boa árvore dá bons frutos, mas a arvore má dá frutos maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 18, 'A boa árvore não pode dar frutos maus, nem a árvore má dar bons frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 19, 'Toda árvore que não dá bom fruto é cortada e lançada ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 20, 'Portanto vós os conhecereis pelos seus frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 21, 'Não é qualquer um que me diz: “Senhor, Senhor” que entrará no Reino dos céus; mas sim aquele que faz a vontade do meu Pai que está nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 22, 'Muitos me dirão naquele dia: “Senhor, Senhor! Não profetizamos em teu nome? E em teu nome não expulsamos os demônios? E em teu nome não fizemos muitas maravilhas?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 23, 'Então claramente lhes direi: “Nunca vos conheci. Afastai-vos de mim, transgressores!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 24, 'Portanto todo o que ouve estas minhas palavras e as pratica, eu o compararei ao homem prudente, que construiu sua casa sobre a rocha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 25, 'E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela não caiu, porque estava fundada sobre a rocha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 26, 'Porém todo o que ouve estas minhas palavras e não as pratica, eu o compararei ao homem tolo, que construiu sua casa sobre a areia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 27, 'E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela caiu, e sua queda foi grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 28, 'E aconteceu que, quando Jesus terminou estas palavras, as multidões estavam admiradas de sua doutrina,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 7, 29, 'porque ele os ensinava como tendo autoridade, e não como os escribas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 1, 'Quando ele desceu do monte, muitas multidões o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 2, 'E eis que um leproso veio e prostrou-se diante dele, dizendo: Senhor, se quiseres, podes me limpar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 3, 'Jesus estendeu a mão e o tocou, dizendo: Quero, sê limpo. E logo ele ficou limpo de sua lepra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 4, 'Então Jesus lhe disse: Tem o cuidado de dizeres a ninguém; mas vai mostrar-te ao sacerdote, e oferece a oferta que Moisés ordenou, para que lhes haja testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 5, 'Quando Jesus entrou em Cafarnaum, veio a ele um centurião, rogando-lhe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 6, 'E dizendo: Senhor, o meu servo jaz em casa, paralítico, e gravemente atormentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 7, 'E Jesus lhe disse: Eu irei, e o curarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 8, 'E o centurião respondeu: Senhor, não sou digno de que entres sob meu telhado; mas dize somente uma palavra, e o meu servo sarará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 9, 'Pois eu também sou homem debaixo de autoridade, e tenho debaixo de meu comando soldados; e digo a este: “Vai”, e ele vai; e ao outro: “Vem”, e vem; e a meu servo: “Faze isto”, e ele faz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 10, 'Quando Jesus ouviu [isto] , maravilhou-se, e disse aos que o seguiam: Em verdade vos digo que nem mesmo em Israel encontrei tanta fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 11, 'Mas eu vos digo que muitos virão do oriente e do ocidente, e se sentarão à mesa com Abraão, Isaque, e Jacó, no Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 12, 'Os filhos do reino, porém, serão lançados nas trevas de fora; ali haverá pranto e ranger de dentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 13, 'Então Jesus disse ao centurião: Vai, e assim como creste, a ti seja feito.E naquela mesma hora o servo dele foi sarado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 14, 'E quando Jesus veio à casa de Pedro, viu a sogra dele, deitada e com febre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 15, 'Ele tocou a mão dela, e a febre a deixou. Então ela se levantou e começou a servi-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 16, 'Quando chegou o anoitecer, trouxeram-lhe muitos endemoninhados. Ele expulsou-lhes os espíritos com a palavra, e curou todos os que estavam doentes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 17, 'Para que se cumprisse o que havia sido dito pelo profeta Isaías, que disse: Ele tomou sobre si as nossas enfermidades, e levou as nossas doenças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 18, 'E Jesus, ao ver muitas multidões ao redor de si, mandou que passassem para a outra margem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 19, 'Então um escriba se aproximou, e disse-lhe: Mestre, eu te seguirei aonde quer que fores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 20, 'Jesus lhe respondeu: As raposas têm covis, e as aves do céu ninhos; mas o Filho do homem não tem onde recostar a cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 21, 'E outro dos seus discípulos lhe disse: Senhor, permite-me ir primeiro enterrar meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 22, 'Porém Jesus lhe disse: Segue-me, e deixa aos mortos enterrarem seus mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 23, 'Então ele entrou no barco, e seus discípulos o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 24, 'E eis que se levantou no mar uma tormenta tão grande que o barco era coberto pelas ondas; porém ele dormia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 25, 'E seus discípulos se aproximaram para acordá-lo, dizendo: Senhor, salva-nos! Estamos sendo destruídos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 26, 'E ele lhes respondeu: Por que temeis, [homens] de pouca fé? Então ele se levantou e repreendeu os ventos e o mar. E houve grande calmaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 27, 'E aqueles homens se maravilharam, dizendo: Quem é este, que até os ventos e o mar lhe obedecem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 28, 'E quando chegou à outra margem, à terra dos gergesenos, vieram-lhe ao encontro dois endemoninhados que tinham saído dos sepulcros. Eles eram tão ferozes que ninguém podia passar por aquele caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 29, 'E eis que gritaram, dizendo: Que temos contigo, Jesus, Filho de Deus? Vieste aqui nos atormentar antes do tempo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 30, 'Enquanto isso longe deles estava uma manada de muitos porcos pastando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 31, 'E os demônios rogaram-lhe, dizendo: Se nos expulsares, permite-nos entrar naquela manada de porcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 32, 'E ele lhes disse: Ide. Então eles saíram, e entraram na manada de porcos; e eis que toda aquela manada de porcos se lançou de um precipício ao mar, e morreram nas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 33, 'E os que cuidavam dos porcos fugiram; e ao chegarem à cidade, anunciaram todas [estas] coisas, inclusive o que [havia acontecido] aos endemoninhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 8, 34, 'E eis que toda aquela cidade saiu ao encontro de Jesus; e quando o viram, rogaram-lhe que se retirasse do território deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 1, 'Então ele entrou no barco, passou para a outra margem, e veio à sua própria cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 2, 'E eis que lhe trouxeram um paralítico, deitado em um leito. Quando Jesus viu a fé deles, disse ao paralítico: Tem bom ânimo, filho! Teus pecados são perdoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 3, 'E eis que alguns dos escribas disseram entre si: Ele blasfema.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 4, 'Mas Jesus, conhecendo seus pensamentos, disse: “Por que pensais o mal em vossos corações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 5, 'Pois o que é mais fácil? Dizer: ‘Teus pecados estão perdoados’, ou dizer: ‘Levanta-te, e anda’?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 6, 'Ora, para que saibais que o Filho do homem tem autoridade na terra para perdoar pecados”, (Ele, então, disse ao paralítico): Levanta-te, toma o teu leito, e vai para tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 7, 'E este se levantou e foi para sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 8, 'Quando as multidões viram [isto] , ficaram maravilhadas, e glorificaram a Deus, que tinha dado tal autoridade aos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 9, 'E Jesus, ao passar dali, viu um homem sentado na coletoria de impostos, chamado Mateus; e disse-lhe: Segue-me. Então este se levantou e o seguiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 10, 'E aconteceu que, enquanto [Jesus] estava reclinado à mesa na casa [de Mateus] , eis que muitos publicanos e pecadores vieram e se reclinaram à mesa juntamente com Jesus e seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 11, 'E quando os fariseus viram [isto] , perguntaram aos seus discípulos: Por que o vosso Mestre come com publicanos e pecadores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 12, 'Porém Jesus ouviu, e respondeu-lhes: Os que têm saúde não precisam de médico, mas sim os que estão doentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 13, 'Mas ide aprender o que significa: ‘Quero misericórdia, e não sacrifício’. Porque eu não vim chamar os justos, mas sim, os pecadores, ao arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 14, 'Então os discípulos de João vieram a ele, e perguntaram: Por que nós e os fariseus jejuamos muitas vezes, mas os teus discípulos não jejuam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 15, 'E Jesus lhes respondeu: Podem, por acaso, os convidados do casamento andar tristes enquanto o noivo está com eles? Mas dias virão, quando o noivo lhes for tirado, e então jejuarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 16, 'E ninguém põe remendo de pano novo em roupa velha; porque tal remendo rasga a roupa, e o rompimento se torna pior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 17, 'Nem põem vinho novo em odres velhos; pois senão os odres se rompem, o vinho se derrama, e os odres se perdem; mas põem o vinho novo em odres novos, e ambos juntamente se conservam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 18, 'Enquanto ele lhes dizia estas coisas, eis que um chefe [de sinagoga] veio prostrar-se diante dele, e disse: Minha filha faleceu ainda agora; mas vem, e põe tua mão sobre ela, e ela viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 19, 'Então Jesus se levantou e o seguiu com seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 20, '(Eis, porém, que uma mulher enferma de um fluxo de sangue havia doze anos veio por detrás [dele] , e tocou a borda de sua roupa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 21, 'Porque dizia consigo mesma: Se eu tão-somente tocar a roupa dele, serei curada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 22, 'Jesus se virou e a viu. Então disse: Tem bom ânimo, filha, a tua fé te sarou. E desde aquela hora a mulher ficou com saúde.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 23, 'Quando Jesus chegou à casa daquele chefe, viu os tocadores de flauta e a multidão que fazia alvoroço,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 24, 'E disse-lhes: Retirai-vos, porque a menina não está morta, mas sim dormindo. E riram dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 25, 'Mas quando a multidão foi expulsa, ele entrou, pegou a mão dela, e a menina se levantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 26, 'E esta notícia se espalhou por toda aquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 27, 'E saindo Jesus dali, dois cegos o seguiram, gritando: Tem compaixão de nós, Filho de Davi!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 28, 'E quando ele entrou em casa, os cegos vieram a ele. Jesus lhes perguntou: Credes que posso fazer isto? Eles lhe responderam: Sim, Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 29, 'Então tocou os olhos deles, dizendo: Seja feito convosco conforme a vossa fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 30, 'E os olhos deles se abriram. Então Jesus os advertiu severamente, dizendo: Tende o cuidado de que ninguém saiba disso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 31, 'Porém eles saíram e divulgaram a notícia acerca dele por toda aquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 32, 'Enquanto eles saíam, eis que lhe trouxeram um homem mudo e endemoninhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 33, 'Quando o demônio foi expulso, o mudo passou a falar. Então as multidões ficaram maravilhadas, e disseram: Nunca se viu algo assim em Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 34, 'Mas os fariseus diziam: É pelo chefe dos demônios que ele expulsa os demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 35, 'Jesus percorria todas as cidades e aldeias, ensinando em suas sinagogas, pregando o Evangelho do Reino, e curando toda enfermidade e toda doença entre o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 36, 'Quando ele viu as multidões, teve compaixão delas, porque andavam cansadas e desamparadas, como ovelhas que não têm pastor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 37, 'Então disse aos seus discípulos: Em verdade a colheita é grande, porém os trabalhadores são poucos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 9, 38, 'Portanto rogai ao Senhor da colheita que envie trabalhadores à sua colheita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 1, '[Jesus] chamou a si os seus doze discípulos, e deu-lhes poder sobre os espíritos imundos, para os expulsarem, e curarem toda enfermidade e toda doença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 2, 'E os nomes dos doze apóstolos são estes: o primeiro, Simão, chamado Pedro, e seu irmão André; Tiago, [filho] de Zebedeu, e seu irmão João;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 3, 'Filipe e Bartolomeu; Tomé, e Mateus o publicano; Tiago, [filho] de Alfeu; e Lebeu, por sobrenomeTadeu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 4, 'Simão o zeloso, e Judas Iscariotes, o mesmo que o traiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 5, 'Jesus enviou esses doze, e lhes mandou, dizendo: Não ireis pelo caminho dos gentios, nem entrareis em cidade de samaritanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 6, 'Em vez disso, ide às ovelhas perdidas da casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 7, 'E quando fordes, proclamai, dizendo: ‘Perto está o Reino dos céus’.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 8, 'Curai os doentes, limpai os leprosos, ressuscitai os mortos, expulsai os demônios; recebestes de graça, dai de graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 9, 'Não tomeis convosco ouro, nem prata, nem cobre em vossos cintos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 10, 'nem bolsas para o caminho, nem duas túnicas, nem sandálias, nem bordão; pois o trabalhador é digno de seu alimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 11, 'E em qualquer cidade ou aldeia que entrardes, informai-vos de quem nela seja digno, e ficai ali até que saiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 12, 'E quando entrardes na casa, saudai-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 13, 'Se a casa for digna, venha sobre ela a vossa paz; mas se ela não for digna, volte para vós a vossa paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 14, 'E quem quer que não vos receber, nem ouvir vossas palavras, quando sairdes daquela casa ou cidade, sacudi o pó de vossos pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 15, 'Em verdade vos digo que no dia do julgamento mais tolerável será para a região de Sodoma e Gomorra do que para aquela cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 16, 'Eis que eu vos envio como ovelhas em meio de lobos; portanto, sede prudentes como as serpentes e inofensivos como pombas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 17, 'Porém tende cuidado com as pessoas; porque vos entregarão em tribunais, e vos açoitarão em suas sinagogas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 18, 'E até perante governadores e reis sereis levados por causa de mim, para que haja testemunho a eles e aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 19, 'Mas quando vos entregarem, não estejais ansiosos de como ou que falareis; porque naquela mesma hora vos será dado o que deveis falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 20, 'Porque não sois vós os que falais, mas sim o Espírito do vosso Pai que fala em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 21, 'E irmão entregará irmão à morte, e pai ao filho; e filhos se levantarão contra os pais, e os matarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 22, 'E sereis odiados por todos por causa de meu nome; mas aquele que perseverar até o fim, esse será salvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 23, 'Quando, então, vos perseguirem nesta cidade, fugi para outra; porque em verdade vos digo que não acabareis de [percorrer] as cidades de Israel, até que venha o Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 24, 'O discípulo não é superior ao mestre, nem o servo superior ao seu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 25, 'Seja suficiente ao discípulo ser como o seu mestre, e ao servo como o seu senhor; se ao chefe da casa chamaram de Belzebu, quanto mais aos membros de sua casa!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 26, 'Portanto, não os temais; porque nada há encoberto que não se revelará, [nada] oculto que não se saberá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 27, 'O que eu vos digo em trevas, dizei na luz; e o que ouvis ao ouvido, proclamai sobre os telhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 28, 'E não temais os que matam o corpo, mas não podem matar a alma; temei mais aquele que pode destruir tanto a alma como o corpo no inferno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 29, 'Não se vendem dois pardais por uma pequena moeda? Mas nem um deles cairá em terra contra a vontade de vosso Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 30, 'E até os cabelos de vossas cabeças estão todos contados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 31, 'Assim, não tenhais medo; mais valeis vós que muitos pardais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 32, 'Portanto, todo aquele que me der reconhecimento diante das pessoas, também eu o reconhecerei diante de meu Pai, que está nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 33, 'Porém qualquer um que me negar diante das pessoas, também eu o negarei diante de meu Pai, que está nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 34, 'Não penseis que vim trazer paz à terra. Não vim trazer paz, mas sim espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 35, 'Porque eu vim pôr em discórdia ‘o homem contra seu pai, a filha contra sua mãe, e a nora contra sua sogra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 36, 'E os inimigos do homem serão os de sua própria casa’.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 37, 'Quem ama pai ou mãe mais que a mim não é digno de mim; e quem ama filho ou filha mais que a mim não é digno de mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 38, 'E quem não toma sua cruz e segue após mim não é digno de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 39, 'Quem achar sua vida a perderá; e quem, por causa de mim, perder sua vida, a achará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 40, 'Quem vos recebe, recebe a mim; e quem me recebe, recebe aquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 41, 'Quem recebe um profeta por reconhecê-lo como profeta receberá recompensa de profeta; e quem recebe um justo por reconhecê-lo como justo receberá recompensa de justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 10, 42, 'E qualquer um que der ainda que somente um copo de [água] fria a um destes pequenos por reconhecê-lo como discípulo, em verdade vos digo que de maneira nenhuma perderá sua recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 1, 'Quando Jesus acabou de dar as ordens aos seus doze discípulos, partiu dali para ensinar e para pregar em suas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 2, 'E João, ao ouvir na prisão as obras de Cristo, enviou [-lhe] dois de seus discípulos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 3, 'Perguntando-lhe: És tu aquele que havia de vir, ou esperamos outro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 4, 'Jesus lhes respondeu: Ide anunciar a João as coisas que ouvis e vedes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 5, 'Os cegos veem, e os mancos andam; os leprosos são limpos, e os surdos ouvem; os mortos são ressuscitados, e aos pobres é anunciado o Evangelho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 6, 'E bendito é aquele que não se ofender em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 7, 'Depois que eles se foram, Jesus começou a dizer às multidões acerca de João: Que saístes ao deserto para ver? Uma cana que se move pelo vento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 8, 'Mas que saístes para ver? Um homem vestido com roupas delicadas? Eis que os que usam roupas delicadas estão nas casas dos reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 9, 'Mas que saístes para ver? Um profeta? Sim, eu vos digo, e muito mais que um profeta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 10, 'Porque este é aquele sobre o qual está escrito: ‘Eis que diante de tua face envio o meu mensageiro, que preparará o teu caminho diante de ti.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 11, 'Em verdade vos digo que, dentre os nascidos de mulheres, não se levantou [outro] maior que João Batista; porém o menor no Reino dos céus é maior que ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 12, 'E desde os dias de João Batista até agora, o Reino dos céus está sujeito à violência, e os que usam de violência se apoderam dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 13, 'Porque todos os profetas e a Lei profetizaram até João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 14, 'E se estais dispostos a aceitar, este é o Elias que havia de vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 15, 'Quem tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 16, 'Mas com quem compararei esta geração? Semelhante é às crianças que se sentam nas praças, e chamam aos seus colegas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 17, 'E dizem: ‘Tocamos flauta para vós, mas não dançastes; cantamos lamentações para vós, mas não chorastes.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 18, 'Porque veio João, sem comer nem beber, e dizem: ‘Ele tem demônio.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 19, 'Veio o Filho do homem, que come e bebe, e dizem: ‘Eis aqui um homem comilão e beberrão, amigo de publicanos e pecadores!’ Mas a sabedoria prova-se justa por meio de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 20, 'Então ele começou a repreender as cidades em que a maioria de seus milagres haviam sido feitos, por não terem se arrependido:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 21, 'Ai de ti Corazim! Ai de ti Betsaida! Porque se em Tiro e em Sidom tivessem sido feitos os milagres que em vós foram feitos, há muito tempo teriam se arrependido com saco e com cinza!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 22, 'Porém eu vos digo que mais tolerável será para Tiro e Sidom, no dia do juízo, que para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 23, 'E tu, Cafarnaum, que estás exaltada até o céu, ao Xeol serás derrubada! Pois se em Sodoma tivessem sido feitos os milagres que foram feitos em ti, ela teria permanecido até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 24, 'Porém eu vos digo que mais tolerável será para os da região de Sodoma, no dia de juízo, que para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 25, 'Naquele tempo Jesus pronunciou: Graças te dou, Pai, Senhor do céu e da terra, porque escondeste estas coisas aos sábios e entendidos, e as revelaste às crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 26, 'Sim, Pai, porque assim foi agradável a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 27, 'Todas as coisas me foram entregues pelo meu Pai; e ninguém conhece o Filho, a não ser o Pai; nem ninguém conhece o Pai, a não ser o Filho, e a quem o Filho [o] quiser revelar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 28, 'Vinde a mim todos vós que estais cansados e sobrecarregados, e eu vos farei descansar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 29, 'Tomai sobre vós o meu jugo e aprendei de mim, porque sou manso e humilde de coração; e encontrareis descanso para as vossas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 11, 30, 'Pois o meu jugo é suave, e minha carga é leve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 1, 'Naquele tempo Jesus estava indo pelas plantações de cereais no sábado. Seus discípulos tinham fome, e começaram a arrancar espigas e a comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 2, 'Quando os fariseus viram, disseram-lhe: Eis que os teus discípulos fazem o que não é lícito fazer no sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 3, 'Ele, porém, lhes disse: Não lestes o que Davi fez quando teve fome, ele e os que com ele estavam,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 4, 'Como ele entrou na casa de Deus, e comeu os pães da proposição, que a ele não era lícito comer, nem também aos que com ele estavam, a não ser somente aos sacerdotes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 5, 'Ou não lestes na Lei que, nos sábados, os sacerdotes no Templo profanam o sábado, sem se tornarem culpados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 6, 'Eu, porém, vos digo que o maior que o Templo está aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 7, 'Mas se vós soubésseis o que significa: ‘Quero misericórdia, e não sacrifício’, não condenaríeis os inocentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 8, 'Porque o Filho do homem é Senhor até do sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 9, 'E partindo dali, [Jesus] entrou na sinagoga deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 10, 'E eis que havia ali um homem que tinha uma mão definhada; e eles, a fim de o acusarem, perguntaram-lhe: É lícito curar nos sábados?')
